const buffer = Buffer.from(html, 'utf-8');
const filename = `mycroft-report-${new Date().toISOString().split('T')[0]}.html`;

return [{
  json: {
    report_date: new Date().toISOString(),
    total_items: items.length,
    high_priority: highPriority.length,
    critical: critical.length,
    filename: filename
  },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'text/html',
      fileName: filename,
      fileExtension: 'html'
    }
  }
}];

const items = $input.all();
const results = [];

// Financial regulatory keywords to track
const keywordCategories = {
  enforcement: ['enforcement', 'penalty', 'fine', 'violation', 'sanctioned', 'charged', 'settled'],
  compliance: ['compliance', 'audit', 'examination', 'reporting', 'disclosure', 'filing'],
  crypto: ['cryptocurrency', 'crypto', 'bitcoin', 'blockchain', 'digital asset', 'token'],
  securities: ['securities', 'investment advisor', 'investment adviser', 'broker-dealer', 'mutual fund', 'etf'],
  derivatives: ['derivatives', 'futures', 'options', 'swap', 'cftc', 'commodity'],
  fraud: ['fraud', 'misrepresentation', 'ponzi', 'manipulation', 'insider trading', 'scheme']
};

function extractKeywords(text) {
  const lowerText = text.toLowerCase();
  const matched = {};

  for (const [category, keywords] of Object.entries(keywordCategories)) {
    matched[category] = keywords.some(kw => lowerText.includes(kw));
  }

  return matched;
}

function calculateBasicUrgency(title, content) {
  const text = (title + ' ' + content).toLowerCase();
  let score = 5; // baseline

  // Urgency indicators
  if (text.includes('immediate') || text.includes('emergency')) score += 3;
  if (text.includes('deadline') || text.includes('must comply') || text.includes('effective date')) score += 2;
  if (text.includes('enforcement') || text.includes('penalty') || text.includes('fine')) score += 2;
  if (text.includes('new rule') || text.includes('proposed rule') || text.includes('final rule')) score += 1;
  if (text.includes('fraud') || text.includes('manipulation')) score += 1;
  if (text.includes('cease and desist') || text.includes('suspension')) score += 1;

  return Math.min(score, 10);
}

function determineImpactLevel(urgencyScore, isEnforcement, isFraud) {
  if (urgencyScore >= 9 || isFraud) return 'Critical';
  if (urgencyScore >= 7 || isEnforcement) return 'High';
  if (urgencyScore >= 5) return 'Medium';
  return 'Low';
}

for (const item of items) {
  const json = item.json;
  const fullText = `${json.title} ${json.content}`;
  const keywordMatches = extractKeywords(fullText);
  const urgencyScore = calculateBasicUrgency(json.title, json.content);

  results.push({
    json: {
      ...json,
      keyword_matches: keywordMatches,
      urgency_score: urgencyScore,
      impact_level: determineImpactLevel(urgencyScore, keywordMatches.enforcement, keywordMatches.fraud),
      word_count: json.content.split(' ').length,
      has_deadline: fullText.toLowerCase().includes('deadline'),
      is_enforcement: keywordMatches.enforcement,
      categories: Object.entries(keywordMatches).filter(([k, v]) => v).map(([k]) => k)
    }
  });
}

return results;

