// Rows actually inserted return via RETURNING * with a numeric id (and title).
// Conflicted rows return nothing; n8n may emit an empty placeholder item — exclude those.
const newItems = insertResults.filter(i => i.json && Number.isInteger(i.json.id) && i.json.title);

console.log(`📊 Insert summary: ${insertResults.length} processed, ${newItems.length} new, ${insertResults.length - newItems.length} duplicate/empty`);

if (newItems.length === 0) {
  console.log('✅ No new items - all were duplicates!');
  return [];
}

return newItems;
